def main():
    if len(sys.argv) != 2 or sys.argv[1].upper() not in BENCHMARKS:
        raise SystemExit("Usage: python3 tests/bench-native-stage.py "+ "|".join(BENCHMARKS) + "")
    exec(compile(BENCHMARKS[sys.argv[1].upper()], str(Path(__file__).resolve()), "exec"), {"__name__": "__main__", "__file__": __file__})

if __name__ == "__main__":
    main()
